const item = $input.first().json;
const execucao = item.execution || {};
const workflow = item.workflow || {};
const erro = execucao.error || {};

const nomeWorkflow = workflow.name || 'workflow desconhecido';
const nodeComErro = execucao.lastNodeExecuted || 'node desconhecido';
const mensagemErro = erro.message || 'erro sem mensagem';
const linkExecucao = execucao.id && workflow.id ? `https://n8n-n8n.wg1izd.easypanel.host/workflow/${workflow.id}/executions/${execucao.id}` : '';

const texto = `⚠️ Erro no workflow "${nomeWorkflow}"\nNode: ${nodeComErro}\nErro: ${mensagemErro}` + (linkExecucao ? `\n${linkExecucao}` : '');

return [{ json: { texto_erro: texto } }];
